def _cut(s, n):
    s = s or ""
    return s if len(s) <= n else s[:n].rsplit(" ", 1)[0] + "…"


def _build():  # PROBLEMS from the rows and hard.json; run from the repository root
    hard = json.load(open(DATA["problems"]))
    flags = json.load(open(DATA["flags"]))["sets"]["hard"]["flags"]
    clean = sorted(int(i) for i, f in flags.items() if f["flag"] == "none")
    assert len(clean) == DATA["n"], len(clean)
    rows = {}
    for arm in ARMS:
        rs = [json.loads(line) for line in open(DATA["rows"] + arm + ".jsonl")]
        rows[arm] = {r["problem_index"]: r for r in rs}
        assert len(rs) == DATA["n"] and sorted(rows[arm]) == clean, arm
    out = []
    for i in clean:
        h = hard[i]
        for arm in ARMS:
            r = rows[arm][i]
            assert r["gold"] == h["answer"] and r["unique_id"] == h["unique_id"] and len(r["tail"]) <= DATA["tail"], (arm, i)
            assert not r["cap_hit"] or r["n_new"] == DATA["new"], (arm, i)
        out.append([i, h["source"], _cut(h["problem"], 420), h["answer"]] +
                   [[r["n_new"], int(r["cap_hit"]), r["score_v3"], _cut(r["extracted_v3"], 36), r["tail"]]
                    for r in (rows[arm][i] for arm in ARMS)])
    return out, rows


# Counts from PROBLEMS, per arm: right and cut off at an allowance, tokens per problem, and the answers past 16,384
def _at(j, cap):
    a = [p[4 + j] for p in PROBLEMS]
    done = [x for x in a if not x[1] and x[0] <= cap]
    return {"right": sum(x[2] for x in done), "cut": len(a) - len(done), "finished": len(done),
            "tokens": round(sum(min(x[0], cap) for x in a) / len(a), 1)}


def _late(j):
    late = [p[4 + j] for p in PROBLEMS if p[4 + j][0] > DATA["old"]]
    return {"n": len(late), "finished": sum(not x[1] for x in late), "right": sum(x[2] for x in late)}


COUNTS = {arm: {"old": _at(j, DATA["old"]), "new": _at(j, DATA["new"]), "late": _late(j)} for j, arm in enumerate(ARMS)}

_S, _Rl = DATA["cells"]["sft_cue"], DATA["cells"]["rl_plain"]
_pct = lambda a, b: f"{100 * a / b:.1f} %"
_iv = lambda c: f"95 % interval {c[0]:.1f} to {c[1]:.1f}"
_t = lambda x: f"{round(x):,}"
_sl, _so = _S["of_them_finished"] - _S["of_them_right"], COUNTS["sft_cue"]["old"]  # long answers that end wrong; those within 16,384

